// ---------- 钉钉在线文档面板：webview 嵌 alidocs 原样查看/编辑 + dws 拉 Markdown 喂终端 agent ----------
const dingtalk = {
  spaces: [],
  cur: null,   // 当前打开的文档节点
  curMd: '',   // 当前文档 markdown（甩给 agent 用）
  webview: null,
  loaded: false,

  isOpen() { return !$('#dingtalk-panel').classList.contains('hidden'); },
  toggle() { this.isOpen() ? this.close() : this.open(); },
  open() {
    if (term.maximized) term.toggleMax(false);
    $('#main-body').classList.add('dt-open');
    $('#dingtalk-panel').classList.remove('hidden');
    $('#btn-dingtalk').classList.add('active');
    if (!this.loaded) this.loadSpaces();
  },
  close() {
    $('#main-body').classList.remove('dt-open');
    $('#dingtalk-panel').classList.add('hidden');
    $('#btn-dingtalk').classList.remove('active');
  },

  esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); },
  setStatus(msg, isErr) { const el = $('#dt-status'); if (!el) return; el.textContent = msg || ''; el.classList.toggle('err', !!isErr); },

  // 统一收口后端返回：runDws 包成 {ok,data}；业务错误是 {ok:false,error}
  async api(path) {
    try {
      const r = await (await fetch(path)).json();
      if (r && r.ok === false) return { ok: false, error: r.error || '调用失败' };
      return (r && r.data !== undefined) ? { ok: true, data: r.data } : { ok: true, data: r };
    } catch (e) { return { ok: false, error: e.message }; }
  },

  async loadSpaces() {
    this.setStatus('加载知识库…');
    const r = await this.api('/api/dingtalk/spaces');
    if (!r.ok) { this.setStatus(r.error, true); this.renderLoginHint(r.error); return; }
    this.spaces = (r.data && r.data.wikiSpaces) || [];
    this.loaded = true;
    this.setStatus(this.spaces.length + ' 个知识库');
    const tree = $('#dt-tree');
    tree.innerHTML = '';
    this.spaces.forEach((sp) => tree.appendChild(this.rowSpace(sp)));
  },
  renderLoginHint(err) {
    $('#dt-tree').innerHTML = `<div class="dt-empty">无法读取钉钉知识库<br><span style="font-size:11.5px">${this.esc(err)}<br>请在终端执行 <b>dws auth login</b> 后点 ⟳ 重试</span></div>`;
  },

  // 知识库（wiki space）作为根节点，展开拉一级文档节点
  rowSpace(sp) {
    const wrap = document.createElement('div');
    const row = document.createElement('div');
    row.className = 'dt-node';
    row.innerHTML = `<span class="dt-tw">▸</span><span class="dt-name">${this.esc(sp.name)}</span>`;
    const kids = document.createElement('div');
    kids.className = 'dt-children'; kids.style.display = 'none';
    let loaded = false;
    row.onclick = async () => {
      const show = kids.style.display === 'none';
      kids.style.display = show ? '' : 'none';
      row.querySelector('.dt-tw').textContent = show ? '▾' : '▸';
      if (show && !loaded) {
        loaded = true;
        kids.innerHTML = '<div class="dt-node" style="opacity:.6">加载中…</div>';
        const r = await this.api('/api/dingtalk/tree?workspace=' + encodeURIComponent(sp.workspaceId));
        this.fillChildren(kids, r);
      }
    };
    wrap.appendChild(row); wrap.appendChild(kids);
    return wrap;
  },
  // 文档/文件夹节点：文件夹可展开，文档点开加载
  rowNode(n) {
    const isFolder = n.nodeType === 'folder' || n.hasChildren;
    const wrap = document.createElement('div');
    const row = document.createElement('div');
    row.className = 'dt-node';
    row.innerHTML = `<span class="dt-tw">${isFolder ? '▸' : '·'}</span><span class="dt-name">${this.esc(n.name)}</span>`;
    if (isFolder) {
      const kids = document.createElement('div');
      kids.className = 'dt-children'; kids.style.display = 'none';
      let loaded = false;
      row.onclick = async () => {
        const show = kids.style.display === 'none';
        kids.style.display = show ? '' : 'none';
        row.querySelector('.dt-tw').textContent = show ? '▾' : '▸';
        if (show && !loaded) {
          loaded = true;
          kids.innerHTML = '<div class="dt-node" style="opacity:.6">加载中…</div>';
          const r = await this.api('/api/dingtalk/tree?workspace=' + encodeURIComponent(n.workspaceId) + '&folder=' + encodeURIComponent(n.nodeId));
          this.fillChildren(kids, r);
        }
      };
      wrap.appendChild(row); wrap.appendChild(kids);
    } else {
      row.onclick = () => this.openDoc(n, row);
      wrap.appendChild(row);
    }
    return wrap;
  },
  fillChildren(kids, r) {
    kids.innerHTML = '';
    if (!r.ok) { kids.innerHTML = `<div class="dt-node" style="color:#d9534f">${this.esc(r.error)}</div>`; return; }
    const nodes = (r.data && r.data.nodes) || [];
    if (!nodes.length) { kids.innerHTML = '<div class="dt-node" style="opacity:.6">（空）</div>'; return; }
    nodes.forEach((c) => kids.appendChild(this.rowNode(c)));
  },

  openDoc(n, row) {
    document.querySelectorAll('#dt-tree .dt-node.active').forEach((e) => e.classList.remove('active'));
    if (row) row.classList.add('active');
    this.cur = n; this.curMd = '';
    $('#dt-doc-title').textContent = n.name || '文档';
    $('#dt-open-ext').disabled = !(n.docUrl && /^https?:/.test(n.docUrl));
    $('#dt-send-agent').disabled = true;
    const body = $('#dt-doc-body');
    const desktop = !!(window.fanboxEnv && window.fanboxEnv.isDesktopApp);
    const httpUrl = (n.docUrl && /^https?:/.test(n.docUrl)) ? n.docUrl : '';
    if (desktop && httpUrl) {
      // 桌面：webview 原样加载钉钉在线文档（首次需在 webview 内登录，登录态按 partition 持久化）
      if (!this.webview || this.webview.parentNode !== body) {
        body.innerHTML = '';
        const wv = document.createElement('webview');
        wv.setAttribute('partition', 'persist:dingtalk');
        wv.setAttribute('allowpopups', '');
        this.webview = wv;
        body.appendChild(wv);
      }
      this.webview.src = httpUrl;
      this.loadMarkdown(n, false); // 后台拉 markdown 供「甩给 agent」
    } else {
      // 网页版 / 非 http 链接：退回 dws 拉的 markdown 渲染
      body.innerHTML = '<div class="dt-empty">加载文档内容…</div>';
      this.loadMarkdown(n, true);
    }
  },
  async loadMarkdown(n, renderInBody) {
    const r = await this.api('/api/dingtalk/doc?node=' + encodeURIComponent(n.nodeId));
    if (this.cur !== n) return; // 期间切了文档
    if (r.ok && r.data && typeof r.data.markdown === 'string') {
      this.curMd = r.data.markdown;
      $('#dt-send-agent').disabled = false;
      if (renderInBody) {
        const html = (window.marked && !window.__noMarked) ? window.marked.parse(this.curMd) : '<pre>' + this.esc(this.curMd) + '</pre>';
        $('#dt-doc-body').innerHTML = '<div class="dt-md">' + html + '</div>';
      }
    } else if (renderInBody) {
      const msg = r.ok ? '该节点不是在线文档（可能是表格/链接/文件），用「浏览器打开」查看' : r.error;
      $('#dt-doc-body').innerHTML = `<div class="dt-empty">${this.esc(msg)}</div>`;
    }
  },

  sendToAgent() {
    if (!this.cur) return;
    if (this.curMd) {
      term.sendContext(this.curMd, '钉钉 · ' + (this.cur.name || ''));
    } else {
      term.sendContext(`请用 dws 读取这篇钉钉文档并参考：\ndws doc read --node ${this.cur.nodeId} --content-format markdown\n标题：${this.cur.name}\n链接：${this.cur.docUrl || ''}`, '钉钉');
    }
    toast('已甩给终端 agent');
  },
  openExternal() { if (this.cur && this.cur.docUrl && /^https?:/.test(this.cur.docUrl)) window.open(this.cur.docUrl, '_blank'); },

  async search(q) {
    q = (q || '').trim();
    if (!q) { this.loaded = false; this.loadSpaces(); return; }
    this.setStatus('搜索“' + q + '”…');
    const r = await this.api('/api/dingtalk/search?q=' + encodeURIComponent(q));
    if (!r.ok) { this.setStatus(r.error, true); return; }
    const docs = (r.data && r.data.documents) || [];
    this.setStatus('搜到 ' + docs.length + ' 条（点 ⟳ 返回知识库）');
    const tree = $('#dt-tree');
    tree.innerHTML = '';
    if (!docs.length) { tree.innerHTML = '<div class="dt-empty">没搜到</div>'; return; }
    docs.forEach((d) => tree.appendChild(this.rowNode(d)));
  },

  init() {
    const btn = $('#btn-dingtalk'); if (!btn) return;
    btn.onclick = () => this.toggle();
    $('#dt-close').onclick = () => this.close();
    $('#dt-refresh').onclick = () => { $('#dt-search-input').value = ''; this.loaded = false; this.loadSpaces(); };
    $('#dt-send-agent').onclick = () => this.sendToAgent();
    $('#dt-open-ext').onclick = () => this.openExternal();
    $('#dt-search-input').addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); this.search(e.target.value); } });
    this.initResizer();
  },
  initResizer() {
    const rz = $('#dt-resizer'); const sb = $('#dt-sidebar'); if (!rz || !sb) return;
    let dragging = false;
    rz.addEventListener('mousedown', (e) => { dragging = true; rz.classList.add('dragging'); e.preventDefault(); });
    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const w = Math.max(180, Math.min(480, e.clientX - sb.getBoundingClientRect().left));
      sb.style.width = w + 'px';
    });
    window.addEventListener('mouseup', () => { if (dragging) { dragging = false; rz.classList.remove('dragging'); } });
  },
};
