function runDws(args) {
  return new Promise((resolve) => {
    execFile(DWS_BIN, args, { timeout: 30000, maxBuffer: 16 * 1024 * 1024, windowsHide: true, env: { ...process.env } }, (err, stdout, stderr) => {
