        try { const e = JSON.parse(errRaw); if (e && e.error) return resolve({ ok: false, error: e.error.message || 'dws 返回错误', detail: e.error }); } catch { /* 非 JSON，原样回 */ }
        return resolve({ ok: false, error: /ENOENT/.test(errRaw) ? '未找到 dws，请先安装并执行 dws auth login' : errRaw });
      }
      const msg = ((err && err.message) || 'dws 无输出').trim();
      resolve({ ok: false, error: /ENOENT/.test(msg) ? '未找到 dws，请先安装并执行 dws auth login' : msg });
    });
  });
}

