_mentionCtx(ta) {
  const pos = ta.selectionStart || 0;
  const m = ta.value.slice(0, pos).match(/(?:^|\s)@([^\s@]*)$/);
  if (!m) return null;
  return { term: m[1], start: pos - m[1].length - 1, end: pos };
},
async queryMentions(term) {
  const root = state.cwd || state.home;
  const reqId = (this._mReq = (this._mReq || 0) + 1);
  let items = [];
  try {
    if (term && term.length) {
      const r = await (await fetch('/api/search?q=' + encodeURIComponent(term) + '&root=' + encodeURIComponent(root))).json();
      items = (r.results || []).filter((x) => !x.isDir);
    } else {
      const r = await (await fetch('/api/list?path=' + encodeURIComponent(root))).json();
      items = (r.entries || []).filter((x) => !x.isDir);
    }
  } catch { /* */ }
  if (reqId !== this._mReq) return; // 丢弃过期结果
  this._mItems = items.slice(0, 30); this._mIdx = 0; this.renderMentionPop();
},
renderMentionPop() {
  const pop = $('#chat-mention-pop'); if (!pop) return;
  const items = this._mItems || [];
  if (!items.length) { this.hideMentionPop(); return; }
  const home = state.home || '';
  pop.innerHTML = items.map((it, i) => {
    const rel = (it.path && home && it.path.startsWith(home)) ? '~' + it.path.slice(home.length) : (it.path || '');
    return `<div class="cm-item${i === this._mIdx ? ' sel' : ''}" data-i="${i}"><span class="cm-name">${this.esc(it.name)}</span><span class="cm-path">${this.esc(rel)}</span></div>`;
  }).join('');
  pop.querySelectorAll('.cm-item').forEach((el) => { el.onmousedown = (ev) => { ev.preventDefault(); this.pickMention(Number(el.dataset.i)); }; });
  pop.classList.remove('hidden');
},
hideMentionPop() { const pop = $('#chat-mention-pop'); if (pop) pop.classList.add('hidden'); this._mItems = null; },
mentionPopOpen() { const pop = $('#chat-mention-pop'); return !!(pop && !pop.classList.contains('hidden')); },
pickMention(i) {
  const it = (this._mItems || [])[i]; const ctx = this._mCtx; const ta = $('#chat-input');
  if (!it || !ctx || !ta) { this.hideMentionPop(); return; }
  const token = '@' + it.name + ' ';
  ta.value = ta.value.slice(0, ctx.start) + token + ta.value.slice(ctx.end);
  const pos = ctx.start + token.length; ta.setSelectionRange(pos, pos);
  if (!this.mentions.some((m) => m.path === it.path)) this.mentions.push({ name: it.name, path: it.path });
  this.hideMentionPop(); this.autosize(ta); ta.focus();
},
onKeydown(e) {
  if (this.mentionPopOpen()) {
    const n = (this._mItems || []).length;
    if (e.key === 'ArrowDown') { e.preventDefault(); this._mIdx = Math.min(n - 1, (this._mIdx || 0) + 1); this.renderMentionPop(); return; }
    if (e.key === 'ArrowUp') { e.preventDefault(); this._mIdx = Math.max(0, (this._mIdx || 0) - 1); this.renderMentionPop(); return; }
    if (e.key === 'Enter' || e.key === 'Tab') { e.preventDefault(); this.pickMention(this._mIdx || 0); return; }
    if (e.key === 'Escape') { e.preventDefault(); this.hideMentionPop(); return; }
  }
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); this.send(); }
},
