// 失败再退回 PATH 上的 claude.cmd / claude。
let _claudeBin = null;
function resolveClaude() {
  if (_claudeBin) return _claudeBin;
  if (PLATFORM === 'win32') {
    try {
      const root = require('child_process').execSync('npm root -g', { encoding: 'utf8' }).trim().split(/\r?\n/)[0];
      const exe = path.join(root, '@anthropic-ai', 'claude-code', 'bin', 'claude.exe');
      if (fs.existsSync(exe)) return (_claudeBin = { file: exe, shell: false });
    } catch { /* 落到 .cmd */ }
    return (_claudeBin = { file: 'claude.cmd', shell: true });
  }
  return (_claudeBin = { file: 'claude', shell: false });
}

// Claude Code 无头模式：-p + stream-json 流式；--permission-mode acceptEdits 让它能直接改文件（自动接受编辑）。
// 在 cwd 里运行，可读写该目录文件——这就是「内置一个会改文件的 agent」。
function chatClaude(res, body) {
  const cwd = (body.cwd && fs.existsSync(body.cwd)) ? body.cwd : HOME;
  const { file, shell } = resolveClaude();
  let prompt = String(body.message || '');
  const atts = Array.isArray(body.attachments) ? body.attachments.filter((a) => a && a.path) : [];
  if (atts.length) prompt += '\n\n[附件（请读取以下文件）]\n' + atts.map((a) => a.path).join('\n');
  if (prompt.length > 28000) prompt = prompt.slice(0, 28000) + '\n…（内容过长已截断）'; // 防 Windows 命令行长度上限
  const args = ['-p', prompt, '--output-format', 'stream-json', '--verbose', '--permission-mode', 'acceptEdits', '--add-dir', cwd];
  if (body.sessionId) args.push('--resume', String(body.sessionId));
  let child;
  try { child = spawn(file, args, { cwd, shell, env: process.env, windowsHide: true }); }
  catch (e) { sseSend(res, 'error', { message: 'Claude Code 启动失败：' + e.message }); return res.end(); }
  let buf = ''; let sentSession = body.sessionId || ''; let gotAny = false;
  child.stdout.on('data', (chunk) => {
    buf += chunk.toString('utf8');
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl).trim(); buf = buf.slice(nl + 1);
      if (!line) continue;
      let ev; try { ev = JSON.parse(line); } catch { continue; }
      if (!ev || !ev.type) continue;
      if (ev.session_id && ev.session_id !== sentSession) { sentSession = ev.session_id; sseSend(res, 'session', { id: ev.session_id }); }
      if (ev.type === 'assistant' && ev.message && Array.isArray(ev.message.content)) {
        for (const c of ev.message.content) { if (c.type === 'text' && c.text) { gotAny = true; sseSend(res, 'delta', { text: c.text }); } }
      } else if (ev.type === 'result') {
        sseSend(res, 'result', { text: ev.result || '', isError: !!ev.is_error });
      }
    }
  });
  let errTail = '';
  child.stderr.on('data', (c) => { errTail = (errTail + c.toString('utf8')).slice(-500); });
  child.on('error', (e) => { sseSend(res, 'error', { message: 'Claude Code 启动失败：' + e.message + '（确认已安装 claude）' }); res.end(); });
  child.on('close', (code) => {
    if (!gotAny && code) {
      const tail = errTail.trim();
      sseSend(res, 'error', { message: `Claude Code 退出码 ${code}${tail ? '：' + tail : '（可能未登录：终端里跑一次 claude 登录）'}` });
    }
    sseSend(res, 'done', {});
    res.end();
  });
  res.on('close', () => { try { child.kill(); } catch { /* */ } });
}

